<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api } from './api'
import WorkspaceDialog from './WorkspaceDialog.vue'
const selected=ref<any>(null),configurationOpen=ref(false),artifactBusy=ref(false)
let artifactRequest=0
function closeArtifact(){artifactRequest++;artifact.value=null;artifactBusy.value=false}
const props=defineProps<{scan:string, projectId:string, canReview:boolean}>()
const emit=defineEmits<{tasks:[taskId?:string]}>()
const profiles=ref<any[]>([]), profile=ref(''), page=ref<any>(null), offset=ref(0), busy=ref(false), error=ref(''), artifact=ref<any>(null), artifactName=ref('')
const names:Record<string,string>={PENDING:'等待复核',RUNNING:'正在复核',DONE:'已通过答复与收据校验',TECH_FAILED:'技术失败',STALE:'证据已失效',CONFIRMED:'AI确认存在风险',LIKELY:'AI认为可能有风险',FALSE_POSITIVE:'AI认为静态误报',SAFE:'AI认为条件下安全',NEED_MORE_CONTEXT:'需要补充证据'}
async function refresh(){busy.value=true;error.value='';try{page.value=await api(`/scans/${props.scan}/ai?offset=${offset.value}`);selected.value=page.value.items.find((row:any)=>row.finding_id===selected.value?.finding_id)||null}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function start(mode:string){busy.value=true;error.value='';try{const p=profiles.value.find(p=>p.id===profile.value);if(!p)throw Error('请选择当前工程的复核配置');const task=await api('/tasks','POST',{project_id:p.project_id,profile_id:p.id,revision:p.revision,mode,scan_id:props.scan});emit('tasks',task.id)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function readArtifact(name:string, position=0){if(artifactBusy.value)return;const mine=++artifactRequest;artifactBusy.value=true;error.value='';try{const value=await api(`/scans/${props.scan}/ai-artifact?name=${encodeURIComponent(name)}&offset=${position}`);if(mine===artifactRequest){artifactName.value=name;artifact.value=value}}catch(e:any){if(mine===artifactRequest)error.value=e.message}finally{if(mine===artifactRequest)artifactBusy.value=false}}
function receipts(row:any){const names=new Set<string>();for(const record of [row,...(row.attempts||[])])for(const key of ['packet_file','prompt_file','stdout_file','stderr_file'])if(record[key])names.add(record[key]);return [...names]}
onMounted(async()=>{try{profiles.value=(await api('/profiles')).items.filter((p:any)=>p.project_id===props.projectId);profile.value=profiles.value[0]?.id||'';await refresh()}catch(e:any){error.value=e.message}})
</script>
<template>
  <div class="records-page ai-center"><h1>OpenCode 逐项复核</h1><p>静态分类、AI 答复和人工确认分别保留。打开本页不会调用模型或重新提取 TU。</p><div v-if="error" class="banner error" role="alert">{{error}}</div>
  <p v-if="!canReview" class="banner warning">归档模式缺少本机检查点或原源码，不能重新复核；可查看已有答复与收据。</p><section class="ai-controls"><details :open="configurationOpen" @toggle="configurationOpen=($event.target as HTMLDetailsElement).open"><summary>复核配置与执行说明</summary>
    <label>复核配置<select v-model="profile" aria-label="OpenCode复核配置"><option v-for="p in profiles" :value="p.id">{{p.project_root}} · {{p.id.slice(0,8)}}</option></select></label>
    <p>使用该配置中的 command、provider/model、Worker、超时和重试设置。发起后先验证原输入闭包；模型或工具不可用会记录“技术失败”。</p>
    </details><div class="actions"><button class="primary" :disabled="busy||!canReview||!profile" @click="start('review')">复核全部疑似与未知</button><button :disabled="busy||!canReview||!profile||!page?.states?.TECH_FAILED" @click="start('review-failed')">仅重试技术失败</button><button @click="emit('tasks')">任务日志与安全停止</button><button :disabled="busy" @click="refresh">刷新原始状态</button></div>
  </section>
  <template v-if="page"><div class="records-toolbar"><span>本扫描目标 {{page.total}} 项</span><span v-for="(count,state) in page.states" class="tag">{{names[String(state)]||state}}：{{count}}</span></div><p v-if="!page.total">此结果没有独立 AI 账本；可在静态归档索引查看旧格式记录。未复核不能解释为安全。</p>
  <div class="inspector-layout" :class="{'no-inspector':!selected}"><section class="panel inspector-list"><table class="data-table ai-table"><thead><tr><th>复核对象</th><th>状态</th><th>尝试</th></tr></thead><tbody><tr v-for="row in page.items" :key="row.finding_id" :class="{selected:selected?.finding_id===row.finding_id}"><td><button @click="selected=row">{{row.finding_id}}</button></td><td>{{names[row.state]||row.state}}<small v-if="row.status">{{names[row.status]||row.status}}</small><span v-if="row.error" class="ai-note" :title="row.error"> · 说明</span></td><td>{{row.attempt_count||0}}</td></tr></tbody></table></section>
  <section v-if="selected" class="panel inspector-detail"><div class="page-heading"><h2>答复与完整收据</h2><button @click="selected=null">关闭详情</button></div><p class="identity">{{selected.finding_id}}</p><p>{{names[selected.state]||selected.state}} · {{names[selected.status]||selected.status}}</p><p v-if="selected.error" class="banner" :class="{error:selected.state==='TECH_FAILED'}">{{selected.failure_stage?selected.failure_stage+'：':'执行说明：'}}{{selected.error}}</p><p v-if="selected.answer?.summary">{{selected.answer.summary}}</p><details v-if="selected.answer" open><summary>原始合理化结论、证据与建议</summary><pre>{{JSON.stringify(selected.answer,null,2)}}</pre></details><p>尝试 {{selected.attempt_count||0}} 次 · 格式修复 {{selected.format_fix_count||0}} · 摘要修复 {{selected.summary_fix_count||0}}</p><h3>Packet / 提示词 / 原始响应</h3><div class="receipt-files"><button v-for="name in receipts(selected)" @click="readArtifact(name)">{{name}}</button></div></section></div>
  <div class="page-controls"><button :disabled="busy||!offset" @click="offset=Math.max(0,offset-50);refresh()">上一页</button><p>显示 {{page.total?offset+1:0}}–{{Math.min(offset+50,page.total)}} / {{page.total}}</p><button :disabled="busy||page.next_offset===null" @click="offset=page.next_offset;refresh()">下一页</button></div></template>
  <WorkspaceDialog v-if="artifact" title="AI 复核审计原件" @close="closeArtifact"><p v-if="error" class="banner error" role="alert">{{error}}</p><p class="identity">{{artifactName}} · 字节 {{artifact.offset}}–{{artifact.next_offset??artifact.total}} / {{artifact.total}}</p><pre>{{artifact.text}}</pre><template #footer><button :disabled="artifactBusy||!artifact.offset" @click="readArtifact(artifactName)">回到开始</button><button :disabled="artifactBusy||artifact.next_offset===null" @click="readArtifact(artifactName,artifact.next_offset)">继续完整读取</button></template></WorkspaceDialog></div>
</template>
